fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // We own the Vec<Vec<char>> so we can consume it.
    // max_by_key returns the first element having the maximum key,
    // and None if the iterator is empty.
    strings.into_iter().max_by_key(|s| s.len())
}

